// Block (composition) — a price before and after a discount, read left to right, on a sunken panel.
// Card owns the panel; this Block arranges the two amounts, the arrow between them and the line
// that explains the difference. The discounted amount takes the emphasis ink: a price the product
// flags for attention (naming-convention.md § Text colour roles, row 10). Without `after` there is
// nothing to compare, so the one amount is the price on offer: it takes that ink and no arrow shows.
import type { ReactNode, Ref } from "react";
import { ArrowRight } from "../components/icons";
import { Card, CardContent } from "../components/Card";
import { Separator } from "../components/Separator";
import { Stack } from "../layouts/Stack";
import "./PriceSummary.css";

export interface PriceSummaryAmount {
  /** What the amount is, e.g. "Monthly bill". */
  label: string;
  /** The formatted amount, e.g. "49,000 won". */
  amount: string;
}

export interface PriceSummaryProps {
  /** The price before the discount. Alone (no `after`), it is the price on offer and takes the
   *  emphasis ink itself. */
  before: PriceSummaryAmount;
  /** The price after it; drawn in the emphasis ink. Omit it when no discount applies, e.g. a
   *  "payback included" switch is off: the summary then shows `before` alone, with no arrow. */
  after?: PriceSummaryAmount;
  /** One line saying where the difference comes from. */
  note?: ReactNode;
  /** One small action at the end of the note line, such as a details Button. The panel is a sunken
   *  canvas, so a secondary Button there takes `variant="surface"` (prop-usage-contract.md, canvas). */
  action?: ReactNode;
  className?: string;
  ref?: Ref<HTMLDivElement>;
}

export function PriceSummary({ before, after, note, action, className, ref }: PriceSummaryProps) {
  return (
    <Card ref={ref} variant="sunken" className={className ? `sd-pricesummary ${className}` : "sd-pricesummary"}>
      <CardContent>
        <Stack gap="medium">
          {/* Each amount is its own term-description pair, and the arrow sits between them outside
              both: a `dl` may hold only `dt`, `dd` and `div`, so a glyph cannot go inside one. */}
          <>
            <Stack direction="row" align="end" gap="medium" wrap className="sd-pricesummary__amounts">
              <dl className="sd-pricesummary__amount">
                <dt className="sd-pricesummary__label sd-type-label-medium">{before.label}</dt>
                <dd data-emphasized={after ? undefined : true} className="sd-pricesummary__value sd-type-headline-medium">{before.amount}</dd>
              </dl>
              {after && (
                <>
                  <ArrowRight aria-hidden size="1.5em" className="sd-pricesummary__arrow" />
                  <dl className="sd-pricesummary__amount">
                    <dt className="sd-pricesummary__label sd-type-label-medium">{after.label}</dt>
                    <dd data-emphasized className="sd-pricesummary__value sd-type-headline-medium">{after.amount}</dd>
                  </dl>
                </>
              )}
            </Stack>
          </>
          {(note || action) && (
            <>
              {/* The card's closing row is punctuation the spacing already parts, so the rule is trim. */}
              <Separator isDecorative />
              <Stack direction="row" align="center" justify="between" gap="small" className="sd-pricesummary__footer">
                {note && (
                  <>
                    <p className="sd-pricesummary__note sd-type-body-medium">{note}</p>
                  </>
                )}
                {action}
              </Stack>
            </>
          )}
        </Stack>
      </CardContent>
    </Card>
  );
}

/* PriceSummary.css — .sd-pricesummary (Block)
   Arrangement, plus the ink of this Block's own text (block-contract.md § 5): the amount names are
   supporting text beside the amounts, the amount on offer (the discounted one, or the only one) is
   flagged. Card owns the panel. */
.sd-pricesummary__amounts,
.sd-pricesummary__label,
.sd-pricesummary__value,
.sd-pricesummary__note {
  margin: 0;
}

.sd-pricesummary__amount {
  margin: 0;
  display: flex;
  flex-direction: column;
}

.sd-pricesummary__label {
  color: var(--sd-color-text-muted);
}

.sd-pricesummary__value[data-emphasized] {
  color: var(--sd-color-text-emphasis);
}

/* The arrow reads as a separator between two peers, so it takes the muted ink and sits on the
   amounts' baseline row rather than centred against the two-line columns. */
.sd-pricesummary__arrow {
  flex: none;
  color: var(--sd-color-text-muted);
  margin-block-end: var(--sd-space-2x-small);
}

.sd-pricesummary__note {
  color: var(--sd-color-text-muted);
}
